# A toy BPE-style tokenizer: merge the most common pair of symbols
from collections import Counter

corpus = ["low", "lower", "lowest", "newer", "newest", "wider"]
words = [list(w) for w in corpus]          # start from single characters

for step in range(5):
    pairs = Counter()
    for w in words:
        pairs.update(zip(w, w[1:]))
    (a, b), n = pairs.most_common(1)[0]
    print(f"merge {step + 1}: '{a}' + '{b}' -> '{a + b}' (seen {n} times)")
    new_words = []
    for w in words:
        i, merged = 0, []
        while i < len(w):
            if i < len(w) - 1 and w[i] == a and w[i + 1] == b:
                merged.append(a + b); i += 2
            else:
                merged.append(w[i]); i += 1
        new_words.append(merged)
    words = new_words

vocab = sorted({t for w in words for t in w})
ids = {t: i for i, t in enumerate(vocab)}
for w in words:
    print("".join(w), "->", w, "-> ids", [ids[t] for t in w])
